from langchain_core.tools import tool

@tool
def percent_of(value: float, pct: float) -> float:
    """Return pct percent of value."""
    return value * pct / 100

llm_with_tools = model.bind_tools([percent_of])

msg = llm_with_tools.invoke("What is 17% of 2340?")
for call in msg.tool_calls:
    print(call["name"], call["args"])  # percent_of {'value': 2340, 'pct': 17}

from langchain_core.runnables.history import RunnableWithMessageHistory
from langchain_community.chat_message_histories import ChatMessageHistory

store = {}
def get_history(session_id: str):
    return store.setdefault(session_id, ChatMessageHistory())

conversational = RunnableWithMessageHistory(
    chain, get_history,
    input_messages_key="question",
    history_messages_key="history",
)

conversational.invoke(
    {"question": "What did I just ask?"},
    config={"configurable": {"session_id": "user-42"}},
)
